def f(inp):
    g=[row[:] for row in inp]
    H,W=len(g),len(g[0])
    # templates = non-background objects whose color != 1, i.e. other colors as shapes
    used={}
    for v in set(x for row in g for x in row if x!=0):
        if v==1: continue
        for cp in comps_of(g,v):
            s=norm(cp)
            if s not in used: used[s]=v
